  "sarga": 22,
  "verse": "1",
  "ambiguous_marker": false,
  "sanskrit_iast": "sītāyā vacanaṃ śrutvā paruṣaṃ rākṣasādhipaḥ । pratyuvāca tataḥ sītāṃ vipriyaṃ priyadarśanām ॥1॥",
  "leonov_ru": "Услышав Ситы слова жестокие, владыка ракшасов Ответил тогда Сите, чей облик приятен, неприятное.",
  "commentary": {
    "tilaka": "प्रियदर्शनां सीतां प्रत्यनुनयोक्तिं कृत्वा ततो विप्रियमाहेति संबन्धः",
    "bhusana": "सीताया वचनं श्रुत्वा परुषं राक्षसाधिपः ।\n\nप्रत्युवाच ततः सीतां विप्रियं प्रियदर्शनाम्\nसीताया इत्यादि",
    "siromani": "सीतावचनश्रवणानन्तरकालिकं सीतां प्रति रावणोक्तिमाह सीताया इति । सीतायाः परुषं वचनं श्रुत्वा सीतां प्रत्युवाच"
  },
  "pratika_check": {
    "tilaka": {
      "pratika_iast": "priyadarsanan sitan pratyanunayoktin krtva",
      "matches_verse": true
    },
    "bhusana": {
      "pratika_iast": "sitaya vacanan srutva parusan",
      "matches_verse": true
    },
    "siromani": {
      "pratika_iast": "sitavacanasravananantarakalikan sitan prati ravanoktinaha",
      "matches_verse": true
    }
  }
}
